mapper.select:
/* selectMasterMdCdAgentCardSearchList */ SELECT KAV.AGENT , KAV.BUYER , (SELECT COM_NAME_LOC FROM ICOMCMPY IC WHERE IC.COM_CODE = KAV.BUYER ) AS BUYER_NAME_LOC , (SELECT COM_NAME_LOC FROM ICOMCMPY IC WHERE IC.COM_CODE = KAV.AGENT ) AS COM_NAME_LOC , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE ='K006' AND COD.CODE = KAV.VISIT_TYPE) AS VISIT_TEXT , KAV.VISIT_TYPE , KAV.ADD_USER_ID , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = KAV.ADD_USER_ID) AS ADD_USER_NM , TO_CHAR(TO_DATE(VISIT_DATE||VISIT_TIME,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI') VISIT_DATE , SUBSTR(KAV.VISIT_NOTE,0,50) AS VISIT_NOTE , KAV.IMAGE_KEY , DECODE(KAV.IMAGE_KEY, NULL, '2', '1') AS IMAGE_KEY_IMG , KAV.ADD_USER_DEPT , KAV.ADD_DATE , KAV.ADD_TIME FROM KEP_AGENT_VISIT KAV WHERE 1=1 AND KAV.STATUS != 'D' AND KAV.VISIT_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND KAV.VISIT_TYPE = #{st_visit_kind}
AND KAV.ADD_USER_ID = #{st_kep_user_id}
AND KAV.VISIT_NOTE LIKE '%' || #{st_visit_note} || '%'
AND KAV.BUYER = #{st_buyer_code}
AND KAV.AGENT = #{st_agent_code}
ORDER BY KAV.VISIT_DATE DESC
